using System;using System.Collections.Generic;using System.Linq;using KingmakerMountedCombat.Diagnostics;
namespace KingmakerMountedCombat.Tests {
internal static class BootstrapInventoryProtocolTests {
 private const string Id="11111111-1111-4111-8111-111111111111",NewId="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",NewArea="fedcba9876543210fedcba9876543210";
 private static int Main(){var tests=new TestRunner();
 tests.Run("exact separate minted source request",()=>{var r=Request();TestRunner.Equal(0,r.Validate().Count,string.Join("; ",r.Validate()));TestRunner.Equal("Auto",r.ExpectedNativeLoadType,"Wrong native category.");});
 foreach(var name in new[]{"missing selection","foreign scenario","alias case","base false","second load","write grant","same run","bad source hash","missing input","anchor campaign","anchor archive","wrong leaf","source hash mismatch","schema1","persistence case","route","alternate","bootstrap permission"})tests.Run("cold bridge rejects "+name,()=>{var r=Request();switch(name){case "missing selection":r.BootstrapInventory=null;break;case "foreign scenario":r.Scenario="fixture-intake";break;case "alias case":r.BootstrapInventory.Case="any-inventory";break;case "base false":r.BootstrapInventory.BaseGameOnly=false;break;case "second load":r.BootstrapInventory.ExpectedNativeLoadCount=2;break;case "write grant":r.BootstrapInventory.ExpectedNativeWriteCount=1;break;case "same run":r.BootstrapInventory.SourceRunId=r.RunId;break;case "bad source hash":r.BootstrapInventory.SourceArtifactSha256="bad";break;case "missing input":r.PersistenceLoad=null;break;case "anchor campaign":r.PersistenceLoad.GameId=Id;break;case "anchor archive":r.PersistenceLoad.Sha256=r.Fixture.Working.Sha256;r.BootstrapInventory.SourceArchiveSha256=r.PersistenceLoad.Sha256;break;case "wrong leaf":r.PersistenceLoad.FileName="Auto_2.zks";break;case "source hash mismatch":r.PersistenceLoad.Sha256=new string('e',64);break;case "schema1":r.SchemaVersion=1;break;case "persistence case":r.PersistenceCase="multi-exploration-manual";break;case "route":r.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;case "alternate":r.PersistenceAlternate=r.PersistenceLoad;break;case "bootstrap permission":r.NativeBootstrap=new Chunk7NativeBootstrapSelection();break;}TestRunner.True(r.Validate().Count>0,"Foreign source/authority admitted.");});
 tests.Run("historical Working path remains exact",()=>{var r=Request();r.Scenario="fixture-intake";r.BootstrapInventory=null;r.PersistenceLoad=null;TestRunner.Equal(0,r.Validate().Count,"Historical path narrowed.");});
 tests.Run("closed rows registered",()=>{foreach(var row in new[]{"C7-bootstrap-inventory-source","C7-bootstrap-inventory-native-load","C7-bootstrap-inventory-readonly","C7-bootstrap-inventory-cleanup","C7-bootstrap-inventory-runtime","C7-bootstrap-inventory-interrupted"})TestRunner.True(RuntimeSubscenarioResult.IsMissionScenario(row),"Row missing.");TestRunner.True(!RuntimeSubscenarioResult.IsMissionScenario("C7-bootstrap-inventory-any"),"Open row admitted.");});
 tests.Run("one load consumes only actual admission and no write",()=>{var f=new Fixture();var a=f.Scope();for(int i=0;i<3;i++){TestRunner.True(a.MatchesReadOnlyBootstrapInventoryPlan(f.Source),"Plan refused.");TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Pre-disposal eligibility refused.");}TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Read-only validation spent a load.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"First native load refused.");TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second pre-disposal eligibility admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second actual load admitted.");TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Completed input identity rejected.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Load,f.Root)!=null,"Read-only source wrote.");TestRunner.Equal(1,a.AdmittedNativeLoadRequests,"Wrong admitted load total.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Unexpected write admitted.");});
 foreach(var name in new[]{"load2","uncapped","writable","extra leaf","wrong hash","wrong game","wrong name","wrong area","wrong type","write cap","bootstrap"})tests.Run("neutral readonly plan rejects "+name,()=>{var f=new Fixture();var e=f.Entries();int? loads=1,writes=null;switch(name){case "load2":loads=2;break;case "uncapped":loads=null;break;case "writable":e[0].Writable=true;break;case "extra leaf":e=e.Concat(new[]{new PersistenceSaveEntry{FileName="Auto_2.zks",InternalName="Auto",SaveType="Auto",Area=NewArea,Writable=true}}).ToArray();break;case "wrong hash":f.Source.Sha256=new string('e',64);break;case "wrong game":f.Source.GameId=Id;break;case "wrong name":f.Source.InternalName="other";break;case "wrong area":f.Source.Area=Area;break;case "wrong type":e[0].SaveType="Manual";break;case "write cap":writes=1;break;case "bootstrap":e[0].Campaign="B";e[0].Writable=true;e[0].AdmitsBeforeArea=true;break;}if(name=="bootstrap"){bool refused=false;try{f.Scope(e,loads,writes);}catch(ArgumentException){refused=true;}TestRunner.True(refused,"Invalid bootstrap plan constructed.");}else TestRunner.True(!f.Scope(e,loads,writes).MatchesReadOnlyBootstrapInventoryPlan(f.Source),"Foreign plan admitted.");});
 return tests.Complete();}
 private static RuntimeRequest Request()=>new RuntimeRequest{SchemaVersion=2,RunId="bootstrap-test",Scenario=Chunk7BootstrapInventorySelection.Scenario,BootstrapInventory=new Chunk7BootstrapInventorySelection{Case=Chunk7BootstrapInventorySelection.CaseName,SourceRunId="source-bootstrap",SourceArtifactSha256=new string('c',64),SourceArchiveSha256=new string('d',64),BaseGameOnly=true,ExpectedNativeLoadCount=1,ExpectedNativeWriteCount=0},PersistenceLoad=ColdSource(),Branch="codex/mounted-combat-chunk7-foundation",Commit=new string('1',40),ProductVersion=BuildIdentity.ProductVersion,DllSha256=new string('2',64),DllMvid=Id,TransactionToken=new string('3',64),EvidenceRoot=@"C:\KmcBootstrapVirtual\evidence",Fixture=new RuntimeFixtureIdentity{Baseline=Descriptor("KMC_AUTOMATION_BASELINE","Manual_298_KMC_AUTOMATION_BASELINE.zks",new string('a',64)),Working=Descriptor("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",new string('b',64)),WriteAuthorization=new RuntimeSaveWriteAuthorization{Mode="working-only",AllowedInternalName="KMC_AUTOMATION_WORKING",AllowedFileName="Manual_299_KMC_AUTOMATION_WORKING.zks",BaselineImmutable=true}},QualificationSuite=new RuntimeQualificationSuiteIdentity{SuiteId="bootstrap-suite",SnapshotSha256=new string('4',64)}};
 private static RuntimeSaveDescriptor Descriptor(string n,string f,string h)=>new RuntimeSaveDescriptor{InternalName=n,FileName=f,Sha256=h,Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Id,GameName="Anchor",Area=Area};
 private static RuntimeSaveDescriptor ColdSource()=>new RuntimeSaveDescriptor{InternalName="Autosave",FileName="Auto_1.zks",Sha256=new string('d',64),Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=NewId,GameName="Native",Area=NewArea};
 private sealed class Fixture {
 internal readonly string Root=@"C:\KmcBootstrapVirtual\run\Saved Games";internal RuntimeSaveDescriptor Source=ColdSource();
 internal RuntimeSaveTarget Load=>new RuntimeSaveTarget{InternalName="Autosave",FileName="Auto_1.zks",FullPath=Root+@"\Auto_1.zks",SaveType="Auto",GameId=NewId,GameName="Native",Area=NewArea};
 internal PersistenceSaveEntry[] Entries()=>new[]{new PersistenceSaveEntry{FileName="Auto_1.zks",InternalName="Autosave",SaveType="Auto",Area=NewArea,InitialSha256=new string('d',64)}};
 internal PersistenceSaveAuthorization Scope(PersistenceSaveEntry[] entries=null,int? loads=1,int? writes=null)=>new PersistenceSaveAuthorization(@"C:\KmcBootstrapVirtual\run",NewId,"Native",new string('a',64),entries??Entries(),null,null,writes,loads);
 }
}
internal static class BootstrapVirtualDirectory {internal static IEnumerable<string> EnumerateFileSystemEntries(string path)=>new[]{path+@"\Auto_1.zks"};internal static bool Exists(string path)=>!path.EndsWith(".zks",StringComparison.Ordinal);}
internal static class BootstrapVirtualFile {internal static bool Exists(string path)=>path.EndsWith("Auto_1.zks",StringComparison.Ordinal);internal static void Delete(string path){throw new InvalidOperationException("Unexpected filesystem mutation.");}}
internal static class BootstrapVirtualStorage {internal static void RequireDirectory(string path){if(string.IsNullOrEmpty(path))throw new InvalidOperationException();}internal static string Hash(string path)=>new string('d',64);}
}
